          "a": "হ্যাঁ, ১০০%! প্রজেক্ট সম্পন্ন হওয়ার পর সম্পূর্ণ ক্লিন সোর্স কোড, গিটহাব রিপোজিটরি, ডাটাবেজ এক্সেস এবং সম্পূর্ণ বৌদ্ধিক মালিকানা সরাসরি আপনার কাছে হস্তান্তর করা হবে। এর জন্য কোনো মাসিক রয়্যালটি বা লাইসেন্স ফি দিতে হয় না।"
